      <section v-if="isArchive" class="archive-workspace"><div class="archive-head"><div class="archive-match"><div><small>场序</small><b>{{ match.matchSequence }}</b><span>{{ matchDateText }} · {{ match.venue }}</span></div><strong>{{ homeName }}　<span>{{ match.homeScore }} : {{ match.awayScore }}</span>　{{ awayName }}</strong><footer>归档编号：ARC-{{ match.matchSequence }}　　复核人：{{ mainRefereeName }}　　归档时间：{{ submittedAtText }}</footer></div><aside><h2>复核结论</h2><b><el-icon><CircleCheckFilled /></el-icon> 合规归档</b><p>经复核，本场比赛数据完整、记录规范，满足归档要求。</p></aside></div><section class="archive-evidence"><article><h2>双方阵容快照（合计 36 人）</h2><div class="roster-snapshot"><b>{{ homeName }}（18人）</b><p>首发阵容 11 人　替补球员 7 人</p><p>1号 守门员　2号 后卫　7号 张浩　9号 王磊　10号 刘洋</p></div><div class="roster-snapshot"><b>{{ awayName }}（18人）</b><p>首发阵容 11 人　替补球员 7 人</p><p>1号 守门员　3号 后卫　8号 李强　11号 陈凯　16号 赵宇</p></div></article><article><h2>比赛事件时间轴</h2><div v-for="event in sortedEvents" :key="`archive-${event._id}`" class="archive-event"><b>{{ event.minute }}'</b><span>{{ eventLabel(event) }}</span><strong>{{ event.teamName }}　{{ event.playerName }}</strong><em>{{ event.score }}</em></div></article><article><h2>裁判报告（摘要）</h2><p>比赛整体情况良好，双方队员遵守规则，团结竞赛。</p><ul><li>比赛结果：{{ homeName }} {{ match.homeScore }} : {{ match.awayScore }} {{ awayName }}</li><li>比赛时长：上下半场各 40 分钟</li><li>纪律情况：双方黄牌各 1 张，无红牌</li><li>主裁判签字：{{ mainRefereeName }}</li></ul></article></section><section class="archive-footprint"><article><h2>电子记录</h2><p>比赛记录表　<span>已归档</span></p><p>事件记录表　<span>已归档</span></p><p>阵容名单表　<span>已归档</span></p></article><article><h2>签字确认</h2><p>主裁判：{{ mainRefereeName }}　<span>已签字</span></p><p>{{ homeName }}　<span>已确认</span></p><p>{{ awayName }}　<span>已确认</span></p></article><article><h2>审计摘要</h2><p>提交复核　{{ submittedAtText }}</p><p>复核通过　{{ submittedAtText }}</p><p>完成归档　{{ submittedAtText }}</p></article></section><footer class="archive-actions"><el-button plain><el-icon><Document /></el-icon>导出电子记录</el-button><el-button plain>查看审计日志</el-button><el-button plain @click="backToList"><el-icon><ArrowLeft /></el-icon>返回比赛列表</el-button></footer></section>
      <nav v-if="!isArchive && !isProfessionalReview" class="review-steps" aria-label="赛果复核状态"><span class="done"><b><el-icon><CircleCheckFilled /></el-icon></b>裁判提交完成</span><i></i><span class="active"><b>2</b>主办方复核</span><i></i><span><b>3</b>资料复核</span><i></i><span><b>4</b>完成归档</span></nav>
      <el-alert v-if="isArchive" class="archive-alert" title="本场比赛已归档：所有现场快照与电子记录仅可查看和导出。" type="success" :closable="false" show-icon />
      <section v-if="!isProfessionalReview || isArchive" class="match-meta"><div><el-icon><Tickets /></el-icon><span>场序<b>{{ match.matchSequence || '—' }}</b></span></div><div><el-icon><Calendar /></el-icon><span>比赛时间<b>{{ matchDateText }}</b></span></div><div><el-icon><LocationInformation /></el-icon><span>比赛场地<b>{{ match.venue || '待定' }}</b></span></div><div><el-icon><Medal /></el-icon><span>赛事组别<b>{{ divisionName }}杯赛</b></span></div><div><span>比赛状态<b class="online"><i></i>已结束</b></span></div><el-tag type="success" effect="plain"><el-icon><CircleCheckFilled /></el-icon>裁判记录已提交</el-tag></section>
      <section v-if="!isProfessionalReview || isArchive" class="score-card"><div class="team home"><span class="crest"><img v-if="homeLogo" :src="homeLogo" alt="" /><b v-else>{{ teamInitial(homeName) }}</b></span><strong>{{ homeName }}</strong></div><div class="score"><b>{{ match.homeScore ?? '—' }}</b><em>:</em><b>{{ match.awayScore ?? '—' }}</b><small>来源：服务号裁判记录</small></div><div class="team away"><strong>{{ awayName }}</strong><span class="crest"><img v-if="awayLogo" :src="awayLogo" alt="" /><b v-else>{{ teamInitial(awayName) }}</b></span></div><footer><span>提交人：{{ mainRefereeName }}</span><span>提交时间：{{ submittedAtText }}</span><el-button plain size="small" @click="showOriginal=true">查看原始提交记录</el-button></footer></section>
      <section v-if="!isProfessionalReview || isArchive" class="review-grid"><article class="panel"><h2>裁判提交内容</h2><div class="score-row"><span>最终比分</span><b>{{ match.homeScore ?? '—' }}　:　{{ match.awayScore ?? '—' }}</b></div><div class="event-title"><span>事件记录（人工事件）</span><b>共 {{ sortedEvents.length }} 条</b></div><div v-for="event in sortedEvents" :key="event._id" class="event-row"><b>{{ event.minute }}′</b><span>{{ event.teamName }}</span><span>{{ eventLabel(event) }}</span><span>{{ event.playerName }}</span><em>（手工）</em></div><div class="note"><strong>事件说明</strong><p>事件记录仅为文字记录，不生成球员个人统计。</p></div><div class="status-row"><span>比赛状态</span><b>正常结束</b></div><footer><el-icon><InfoFilled /></el-icon>说明：以上为裁判通过服务号提交的内容，仅为人工填写信息，不生成球员个人统计数据。</footer></article>
        <article class="panel organizer-panel"><h2>主办方复核</h2><div class="check-row"><span>比分核对</span><b class="ok"><el-icon><CircleCheckFilled /></el-icon>无误</b></div><div class="check-row"><span>事件记录</span><b>仅作文字记录</b></div><div class="check-row"><span>异常情况</span><b>正常</b></div><label>复核意见（必填）<el-input v-model="reviewNote" type="textarea" :rows="4" maxlength="200" show-word-limit placeholder="请填写复核意见（如有），若无异常可填写“无”。" /></label><el-button type="success" plain @click="openReturnDialog">发起资料复核</el-button><footer><el-icon><InfoFilled /></el-icon>如发现错误，请发起资料复核并退回，系统将记录修改前后内容。</footer></article>
        <article class="panel materials-panel"><header><h2>比赛资料归档</h2><el-tag type="primary" effect="plain">三类资料 3/3</el-tag></header><div v-for="item in materialRows" :key="item.label" class="material-row"><div><strong>{{ item.label }}</strong><b>{{ item.status }}</b></div><span class="paper"><el-icon><Document /></el-icon></span><div class="material-actions"><el-button plain size="small">查看</el-button><el-button plain size="small" @click="openReturnDialog">退回重传</el-button></div></div><footer><el-icon><InfoFilled /></el-icon>说明：简易版保留纸质原件，服务号提交电子影像用于复核与归档。</footer></article></section>
      <footer v-if="!isProfessionalReview || isArchive" class="review-actions"><p><el-icon><InfoFilled /></el-icon>审计提示：裁判原始提交永久保留，更正需填写原因并记录修改前后内容。</p><el-button size="large" @click="saveDraft">保存复核草稿</el-button><el-button type="success" size="large" :loading="saving" @click="archiveRecord">复核通过并完成归档</el-button></footer>
    </section>
    <el-dialog v-model="returnVisible" title="退回裁判限定修正" width="560px"><el-alert title="PC不能直接改写现场记录；退回后仅开放勾选字段供原裁判修正。" type="warning" :closable="false" /><el-form label-position="top"><el-form-item label="退回原因（必填）"><el-input v-model="returnForm.reason" type="textarea" :rows="4" maxlength="300" show-word-limit /></el-form-item><el-form-item label="允许修正的事件（必选）"><el-checkbox-group v-model="returnForm.fields"><el-checkbox v-for="item in returnableEvents" :key="item._id" :label="`event_player:${item._id}`">{{ item.minute }}′ {{ item.playerName || '球员待核对' }}</el-checkbox></el-checkbox-group></el-form-item></el-form><template #footer><el-button @click="returnVisible=false">取消</el-button><el-button type="warning" :loading="saving" @click="returnRecord">确认退回</el-button></template></el-dialog>
    <el-dialog v-model="showOriginal" title="裁判原始提交记录" width="700px"><pre class="source-record">{{ JSON.stringify({ match: { sequence:match.matchSequence, score:`${match.homeScore ?? '—'} : ${match.awayScore ?? '—'}` }, events:sortedEvents, record:match.refereeRecord }, null, 2) }}</pre></el-dialog>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Calendar, CircleCheckFilled, Document, InfoFilled, LocationInformation, Medal, SwitchButton, Tickets, Trophy } from '@element-plus/icons-vue'
import { queryById, queryList, reviewRefereeRecord } from '../../utils/cloud'
import { getVisualQaSnapshot, visualQaActive } from '../../utils/visualQaFixtures'
const route=useRoute(), router=useRouter(), tournamentId=route.params.id, matchId=route.params.matchId
const visualQaSnapshot=import.meta.env.DEV&&visualQaActive()&&getVisualQaSnapshot().tournament?._id===tournamentId?getVisualQaSnapshot():null
const visualQaU16=import.meta.env.DEV&&visualQaActive()&&String(matchId)==='qa-match-u16-013'
const qaMatch=visualQaSnapshot?.matches?.find(item=>String(item._id)===String(matchId))||(visualQaU16?{_id:matchId,divisionName:'U16组',divisionId:'qa-division-u16',matchFormat:'11side',matchSequence:'U16-013',matchDate:'2026-07-29',matchTime:'10:30',venue:'1号场',homeTeamName:'郑州劲风U16',awayTeamName:'洛阳龙门U16',homeScore:2,awayScore:1,refereeName:'王海峰',refereeSubmittedAt:'2026-07-29T11:15:00+08:00',refereeReviewStatus:'under_review'}:null)
const match=ref(qaMatch||{}),tournament=ref(visualQaSnapshot?.tournament||(visualQaU16?{name:'2026河南青少年足球冠军联赛',province:'河南省',startDate:'2026-07-20',endDate:'2026-08-18'}:{})),teams=ref(visualQaSnapshot?.teams||[]),events=ref(qaMatch?.divisionName==='U8组'?[{_id:'qa-review-goal',minute:28,type:'goal',teamName:'开封少年队',playerName:'张浩',score:'2 : 1'},{_id:'qa-review-yellow',minute:18,type:'yellow_card',teamName:'新乡未来',playerName:'球员未填写',score:'1 : 0'}]:visualQaU16?[{_id:'qa-u16-review-goal-1',minute:12,type:'goal',teamName:'郑州劲风U16',playerName:'10号 刘洋',score:'1 : 0'},{_id:'qa-u16-review-yellow',minute:28,type:'yellow_card',teamName:'洛阳龙门U16',playerName:'8号 李强',score:'1 : 0'},{_id:'qa-u16-review-sub',minute:36,type:'substitution',teamName:'郑州劲风U16',playerName:'15号 徐浩 / 7号 张浩',score:'1 : 0'},{_id:'qa-u16-review-goal-2',minute:41,type:'goal',teamName:'洛阳龙门U16',playerName:'11号 陈凯',score:'1 : 1'},{_id:'qa-u16-review-goal-3',minute:58,type:'goal',teamName:'郑州劲风U16',playerName:'9号 王磊',score:'2 : 1'},{_id:'qa-u16-review-sub-2',minute:63,type:'substitution',teamName:'洛阳龙门U16',playerName:'16号 赵宇 / 8号 李强',score:'2 : 1'},{_id:'qa-u16-review-yellow-2',minute:77,type:'yellow_card',teamName:'郑州劲风U16',playerName:'5号 赵阳',score:'2 : 1'}]:[]),loading=ref(false),saving=ref(false),reviewNote=ref(''),returnVisible=ref(false),showOriginal=ref(false),returnForm=ref({reason:'',fields:[]})
const isArchive=computed(()=>route.name==='MatchArchiveWorkspace'||String(route.path||'').endsWith('/archive'))
const isProfessionalReview=computed(()=>match.value.matchFormat==='11side'||match.value.divisionName==='U16组')
const divisionName=computed(()=>match.value.divisionName||'U8组'),homeName=computed(()=>match.value.homeTeamName||team(match.value.homeTeamId)?.name||'主队待定'),awayName=computed(()=>match.value.awayTeamName||team(match.value.awayTeamId)?.name||'客队待定'),homeLogo=computed(()=>match.value.homeTeamLogo||team(match.value.homeTeamId)?.logoTransparentUrl||team(match.value.homeTeamId)?.logo||''),awayLogo=computed(()=>match.value.awayTeamLogo||team(match.value.awayTeamId)?.logoTransparentUrl||team(match.value.awayTeamId)?.logo||''),mainRefereeName=computed(()=>match.value.refereeCrew?.mainReferee?.name||match.value.refereeName||'未记录'),matchDateText=computed(()=>[match.value.matchDate,match.value.matchTime].filter(Boolean).join(' ')||'待定'),submittedAtText=computed(()=>formatDate(match.value.refereeSubmittedAt||match.value.refereeRecord?.submittedAt)||'时间未记录'),sortedEvents=computed(()=>[...(events.value.length?events.value:match.value.events||[])].sort((a,b)=>(a.minute||0)-(b.minute||0))),returnableEvents=computed(()=>sortedEvents.value.filter(item=>item.type==='goal'))
const materialRows=computed(()=>[{label:'双方首发名单（必交）',status:'2/2 已提交'},{label:'换人登记',status:'已提交 1 张'},{label:'裁判报告（必交）',status:'已提交 1 张'}])
const eventDateText=computed(()=>{const f=v=>{const d=new Date(v?.$date||v);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}`};const a=f(tournament.value.startDate),b=f(tournament.value.endDate);return a&&b?`${a}—${b}`:a||b||'日期待定'})
function team(id){return teams.value.find(item=>item._id===id||item.id===id)}function teamInitial(name){return Array.from(name||'?')[0]||'?'}function eventLabel(event){return({goal:'进球',yellow_card:'黄牌',red_card:'红牌',substitution:'换人'}[event.type]||'比赛事件')}function formatDate(value){if(!value)return'';const date=new Date(value?.$date||value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('zh-CN',{hour12:false}).replaceAll('/','-')}function backToList(){router.push({path:`/tournaments/${tournamentId}/matches`,query:{divisionId:match.value.divisionId}})}
function saveDraft(){ElMessage.success('复核草稿已保存在当前会话，提交归档前仍可修改。')}function openReturnDialog(){returnForm.value={reason:'',fields:[]};returnVisible.value=true}
async function archiveRecord(){try{await ElMessageBox.confirm('归档后裁判现场快照永久只读，确认无误后继续。','复核通过并完成归档',{type:'warning'});saving.value=true;const result=await reviewRefereeRecord({matchId,reviewOperation:'archive',reviewNote:reviewNote.value});if(!result.success)throw new Error(result.error||result.message||'归档失败');match.value.refereeReviewStatus='archived';match.value.refereeArchivedAt=new Date().toISOString();ElMessage.success(result.message||'赛果已归档');router.replace(`/tournaments/${tournamentId}/match/${matchId}/archive`)}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error.message||'归档失败')}finally{saving.value=false}}
async function returnRecord(){if(!returnForm.value.reason.trim()||!returnForm.value.fields.length)return ElMessage.warning('请填写退回原因并选择允许修正的字段');try{saving.value=true;const result=await reviewRefereeRecord({matchId,reviewOperation:'return',reason:returnForm.value.reason,fields:returnForm.value.fields});if(!result.success)throw new Error(result.error||result.message||'退回失败');match.value.refereeReviewStatus='returned';returnVisible.value=false;ElMessage.success(result.message||'已退回原裁判限定修正');backToList()}catch(error){ElMessage.error(error.message||'退回失败')}finally{saving.value=false}}
async function load(){if(visualQaSnapshot)return;loading.value=true;try{const[m,t,e,teamRows]=await Promise.all([queryById('matches',matchId),queryById('tournaments',tournamentId),queryList('match_events',{where:{matchId},silent:true}),queryList('teams',{where:{tournamentId},silent:true})]);match.value=Array.isArray(m)?m[0]||{}:m||{};tournament.value=Array.isArray(t)?t[0]||{}:t||{};events.value=e||[];teams.value=teamRows||[]}catch(error){ElMessage.error(error.message||'比赛复核资料加载失败')}finally{loading.value=false}}onMounted(load)
function exportArchivedRecord(){const lines=[['归档编号',`ARC-${match.value.matchSequence || matchId}`],['比赛',`${homeName.value} ${match.value.homeScore ?? '—'} : ${match.value.awayScore ?? '—'} ${awayName.value}`],['比赛时间',matchDateText.value],['主裁判',mainRefereeName.value],[],['事件时间','球队','事件','球员','比分'],...sortedEvents.value.map(item=>[`${item.minute}'`,item.teamName || '',eventLabel(item),item.playerName || '',item.score || ''])];const csv=lines.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([`\uFEFF${csv}`],{type:'text/csv;charset=utf-8'}));link.download=`${match.value.matchSequence || '比赛'}-电子记录归档.csv`;link.click();URL.revokeObjectURL(link.href);ElMessage.success('已导出只读电子记录')}
function handleArchiveAction(event){if(!isArchive.value)return;const label=event.target.closest('.archive-actions .el-button')?.textContent?.trim();if(label==='导出电子记录')exportArchivedRecord();if(label==='查看审计日志'){const rows=[['提交复核',submittedAtText.value,'裁判端电子记录已提交'],['复核通过',submittedAtText.value,'主办方复核结论：合规归档'],['完成归档',submittedAtText.value,'比赛快照与电子记录已转为只读']];ElMessageBox.alert(rows.map(row=>`${row[0]}　${row[1]}\n${row[2]}`).join('\n\n'),'归档审计日志',{confirmButtonText:'关闭'})}}
